async function loadCustomerSuggestions(q){const host=$('#customer-suggestions');if(!host)return;if(q.trim().length<2){host.innerHTML='';return;}const at=q;const matches=await searchCustomers(q,9);if(state.bill?.customerQuery!==at||!$('#customer-suggestions'))return;host.innerHTML=`<div class="suggest-box flow">${matches.length?`<div class="suggest-help">${T('chooseCustomer')}</div>${matches.map(c=>`<button type="button" class="suggest-item" data-select-customer="${c.id}"><span class="avatar">${E((c.name||c.phone).slice(0,2).toUpperCase())}</span><span><strong>${E(c.name||c.phone)}</strong><small>${E([c.phone,...c.vehicles.map(v=>v.reg)].filter(Boolean).join(' · '))}</small></span></button>`).join('')}`:`<div class="suggest-box flow"><div class="suggest-empty">${T('noMatchContinue')}</div></div>`}</div>`;}
function renderSetup(){return `<main class="setup"><section class="setup-showcase"><div class="showcase-logo"><div class="brand-mark">${I('wheel')}</div><span>TYRE<span>DESK</span></span></div><div class="showcase-copy"><div class="eyebrow">THE WORKSHOP, IN ORDER</div><h1>${T('onboardTitle').replace('Beautifully managed.','<em>Beautifully managed.</em>')}</h1><p>${T('onboardSub')}</p></div><div class="showcase-proof"><span class="proof-pill">${I('shield')}${T('offlineReady')}</span><span class="proof-pill">${I('database')}${T('dataLocal')}</span></div></section><section class="setup-form-area"><form class="setup-form" id="setup-form"><button class="button" type="button" data-action="cloud-login">Sign in to recover a cloud shop</button><div class="setup-progress">${I('wheel')}${T('onboardStep')}</div><h2>${T('onboardCreate')}</h2><p>No accounts needed. Your records stay on this device.</p><button type="button" class="button large" data-action="restore-drive">${I('upload')} Restore from Google Drive backup</button><p class="small-muted">Already used TyreDesk? Restore your previous shop instead of setting it up again.</p><input id="restore-file" type="file" accept=".json,application/json" hidden><div class="field-grid"><div class="field field-spread"><label>${T('businessName')} *</label><input name="name" required maxlength="100" placeholder="e.g. Your Tyre & Alignment Centre" autofocus></div><div class="field"><label>${T('ownerName')} *</label><input name="owner" required maxlength="70" placeholder="Owner's name"></div><div class="field"><label>${T('phone')} *</label><input name="phone" type="tel" required maxlength="20" placeholder="Shop contact"></div><div class="field field-spread"><label>${T('address')}</label><input name="address" maxlength="160" placeholder="Street, shop number, locality"></div><div class="field"><label>${T('city')}</label><input name="city" maxlength="65" placeholder="e.g. Jalna"></div><div class="field"><label>${T('state')}</label><input name="state" maxlength="65" value="Maharashtra"></div><div class="field"><label>${T('language')}</label><select name="language"><option value="en">English</option><option value="hi">हिंदी</option><option value="mr">मराठी</option></select></div><div class="field"><label>${T('prefix')}</label><input name="invoicePrefix" value="INV" maxlength="12" placeholder="INV"></div><div class="field"><label>${T('gstRegistered')}</label><select name="gstRegistered"><option value="false">${T('unregistered')}</option><option value="true">${T('registered')}</option></select></div><div class="field"><label>${T('gstin')} <span class="optional">(${T('optional')})</span></label><input name="gstin" maxlength="15" placeholder="15-character GSTIN"></div><div class="field"><label>${T('password')} *</label><input name="pin" type="password" inputmode="numeric" pattern="[0-9]{4,12}" minlength="4" maxlength="12" required autocomplete="new-password" placeholder="4–12 digits"><small>${T('ownerPinHelp')}</small></div><div class="field"><label>${T('confirmPassword')} *</label><input name="confirmPin" type="password" inputmode="numeric" pattern="[0-9]{4,12}" minlength="4" maxlength="12" required placeholder="Repeat PIN"></div></div><div class="consent"><label><input type="checkbox" name="legalConsent" required> I am authorised to set up this shop, agree to the TyreDesk Terms &amp; Conditions and acknowledge the Privacy Policy.</label><p>Read ${legalLinks()}. Acceptance is required to create a new shop.</p></div><button class="button primary large" type="submit">${T('onboardCreate')} ${I('arrow')}</button><div class="setup-foot">${I('lock')} ${T('securityNote')}</div></form></section></main>`;}
function renderLocked(){const shop=state.data.settings;return `<main class="lock-layout"><div class="lock-art"><div class="showcase-logo"><div class="brand-mark">${I('wheel')}</div><span>TYRE<span>DESK</span></span></div></div><div class="lock-card"><div class="eyebrow">SECURE WORKSPACE</div><h1>${T('locked')}.</h1><p>${E(shop.name)} · ${T('pinPrompt')}</p><form id="unlock-form"><div class="field"><label>${T('password')}</label><input type="password" name="pin" autocomplete="off" inputmode="numeric" pattern="[0-9]{4,12}" minlength="4" maxlength="12" required autofocus placeholder="••••••"></div><button class="button primary large" type="submit">${I('lock')}${T('unlockBtn')}${I('arrow')}</button></form><small class="small-muted" style="margin-top:18px">${T('dataLocal')}</small></div></main>`;}
function settings(){const s=state.data.settings;return header(T('settings'),T('settingsSubtitle'),'PREFERENCES / OWNERSHIP')+`<div class="settings-grid"><div>${cloudPanel()}<section class="setting-panel"><h2>${T('shopProfile')}</h2><p class="lead">Business details are captured on every new invoice. Historical invoices keep their original business details.</p><form id="settings-form"><div class="field-grid"><div class="field field-spread"><label>${T('businessName')}</label><input name="name" required value="${E(s.name)}"></div><div class="field"><label>${T('ownerName')}</label><input name="owner" required value="${E(s.owner)}"></div><div class="field"><label>${T('phone')}</label><input name="phone" required value="${E(s.phone)}"></div><div class="field"><label>${T('whatsapp')}</label><input name="whatsapp" value="${E(s.whatsapp||'')}"></div><div class="field"><label>${T('address')}</label><input name="address" value="${E(s.address||'')}"></div><div class="field"><label>${T('city')}</label><input name="city" value="${E(s.city||'')}"></div><div class="field"><label>${T('state')}</label><input name="state" value="${E(s.state||'')}"></div><div class="field"><label>${T('prefix')}</label><input name="invoicePrefix" value="${E(s.invoicePrefix||'INV')}"></div><div class="field"><label>${T('gstRegistered')}</label><select name="gstRegistered"><option value="false" ${!s.gstRegistered?'selected':''}>${T('unregistered')}</option><option value="true" ${s.gstRegistered?'selected':''}>${T('registered')}</option></select></div><div class="field"><label>${T('gstin')}</label><input name="gstin" maxlength="15" value="${E(s.gstin||'')}"></div><div class="field field-spread"><label>${T('terms')}</label><textarea name="terms" placeholder="Optional service terms, warranty notes…">${E(s.terms||'')}</textarea></div><div class="field field-spread"><label for="payment-qr-file">Shop payment QR (UPI image)</label><input id="payment-qr-file" name="paymentQr" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG or WebP, up to 5 MB. Use a clear, complete QR with its white border. Verify the recipient in your payment app. Saved locally and included in backups.</small>${s.paymentQrData?'<img class="qr-settings-preview" src="'+E(s.paymentQrData)+'" alt="Shop payment QR"><label><input name="removeQr" type="checkbox"> Remove payment QR</label>':''}</div><div class="field field-spread"><label>${T('logo')}</label><input name="logo" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG or WebP · compressed locally, max 3 MB</small>${s.logoData?`<img src="${E(s.logoData)}" alt="Business logo" style="height:53px;width:53px;object-fit:contain;border:1px solid var(--border);border-radius:10px">`:''}</div></div><button class="button primary settings-save" type="submit">${I('check')}${T('saveChanges')}</button></form></section><section class="setting-panel"><h2>${T('language')} & ${T('theme')}</h2><p class="lead">Switch the application language or appearance instantly.</p><div class="field-grid"><div class="field"><label>${T('language')}</label><select id="setting-language"><option value="en" ${s.language==='en'?'selected':''}>English</option><option value="hi" ${s.language==='hi'?'selected':''}>हिंदी</option><option value="mr" ${s.language==='mr'?'selected':''}>मराठी</option></select></div><div class="field"><label>${T('theme')}</label><select id="setting-theme"><option value="light" ${(s.theme||'light')==='light'?'selected':''}>${T('light')}</option><option value="dark" ${s.theme==='dark'?'selected':''}>${T('dark')}</option></select></div></div></section></div><div>${backupSettingsCard()}<section class="setting-panel"><h2>${T('backupRestore')}</h2><p class="lead">${T('backupHint')}</p><div class="setting-actions"><button class="setting-action" data-action="backup-drive">${I('upload')}<span><strong>Back Up to Google Drive</strong><small>Keep a copy safely outside this device</small></span>${I('chevron','trailing')}</button><button class="setting-action" data-action="restore-drive">${I('download')}<span><strong>Restore from Google Drive</strong><small>Recover a shop on this or a new device</small></span>${I('chevron','trailing')}</button><button class="setting-action" data-action="backup">${I('download')}<span><strong>${T('backup')}</strong><small>Export full verified JSON archive</small></span>${I('chevron','trailing')}</button><button class="setting-action" data-action="restore">${I('upload')}<span><strong>${T('restore')}</strong><small>Validate and atomically replace the data</small></span>${I('chevron','trailing')}</button><input id="restore-file" type="file" accept=".json,application/json" hidden></div><div class="muted-note" style="margin-top:18px">${I('alert')} ${T('restoreWarning')}</div></section><section class="setting-panel"><h2>${T('security')}</h2><p class="lead">${T('securityNote')}</p><div class="setting-actions"><button class="setting-action" data-action="change-pin">${I('lock')}<span><strong>${T('changePassword')}</strong><small>Current PIN required</small></span>${I('chevron','trailing')}</button><button class="setting-action" data-action="persist-storage">${I('shield')}<span><strong>Request protected storage</strong><small>Ask browser not to evict local records</small></span>${I('chevron','trailing')}</button><button class="setting-action" data-action="install">${I('mobile')}<span><strong>${T('install')}</strong><small>Make this an app on your device</small></span>${I('chevron','trailing')}</button></div></section><section class="setting-panel"><h2>Terms &amp; Privacy</h2><p>${legalLinks()}</p><p class="small-muted">${s.legalConsent?'Accepted version '+E(s.legalConsent.termsVersion)+' on '+E(new Date(s.legalConsent.acceptedAt).toLocaleString('en-IN')):'This shop predates consent recording; no acceptance has been assumed.'}</p><p>These documents should be reviewed by an Indian legal professional before commercial distribution.</p></section><section class="setting-panel"><h2>${T('storage')}</h2><p class="lead">Everything belongs to this browser profile and web origin.</p><div class="storage-row"><span>Database</span><strong>IndexedDB (local)</strong></div><div class="storage-row"><span>Cloud sync</span><strong>Disabled</strong></div><div class="storage-row"><span>${T('inventory')}</span><strong>${T('onDevice')}</strong></div><div class="storage-row"><span>Shop licence</span><strong>Internal setup edition</strong></div><p class="small-muted" style="margin-top:18px;line-height:1.7">${T('appInfo')} · Always keep a backup outside the browser. Clearing browser/site data may erase records.</p></section></div></div>`;}
function modal(title,subtitle,body,footer='',wide=false){state.modal=`<div class="overlay" data-close-modal><div class="modal ${wide?'xl':''}" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close">${I('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</div></div>`;const h=$('#modal-host');if(h)h.innerHTML=state.modal;}
function closeModal(){state.modal=null;const h=$('#modal-host');if(h)h.innerHTML='';}
function modalButtons(submitId,label=T('save')){return `<button class="button" data-action="close-modal">${T('cancel')}</button><button type="submit" class="button primary" form="${submitId}">${I('check')}${label}</button>`;}
function showCustomerModal(c=null){const vehicles=c?state.data.vehicles.filter(v=>v.customerId===c.id):[];const orders=c?activeOrders().filter(o=>o.customerId===c.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)):[];const spend=orders.reduce((n,o)=>n+o.totals.grandPaise,0),due=orders.reduce((n,o)=>n+o.duePaise,0);
 const body=`${c?`<div class="customer-metrics"><div class="customer-metric"><small>${T('customerSpend')}</small><strong>${M(spend)}</strong></div><div class="customer-metric"><small>${T('customerDue')}</small><strong>${M(due)}</strong></div><div class="customer-metric"><small>${T('invoices')}</small><strong>${orders.length}</strong></div></div>`:''}<form id="customer-form" data-id="${c?.id||''}"><div class="field-grid"><div class="field"><label>${T('name')}</label><input name="name" value="${E(c?.name||'')}" placeholder="Customer name"></div><div class="field"><label>${T('phone')}</label><input name="phone" type="tel" value="${E(c?.phone||'')}" placeholder="Contact number"></div><div class="field field-spread"><label>${T('newVehicle')}</label><input name="vehicle" placeholder="MH 21 AB 1234" value="" /><small>${c?`Current vehicles: ${E(vehicles.map(v=>v.reg).join(', ')||'none')}`:'A new vehicle can be linked here, or when creating an invoice.'}</small></div><div class="field field-spread"><label>${T('notes')}</label><textarea name="notes">${E(c?.notes||'')}</textarea></div></div></form>${c&&orders.length?`<div class="separator"></div><div class="form-section-heading"><h3>${T('customerHistory')}</h3></div><div class="detail-list">${orders.slice(0,12).map(o=>`<button class="detail-row" style="border:0;border-bottom:1px solid var(--border);background:none;width:100%;text-align:left;cursor:pointer;color:var(--ink)" data-invoice="${o.id}"><span>${E(o.number)} · ${fmtDate(o.createdAt,true)}</span><strong>${M(o.totals.grandPaise)}</strong></button>`).join('')}</div>`:''}`;
 modal(c?T('customerDetails'):T('newCustomer'),c?`${E(c.name||c.phone)} · ${E(c.phone||'')}`:T('newCustomerHint'),body,modalButtons('customer-form'));}
function showPriceModal(p=null,forceTyre=false){
 const tyre=forceTyre||p?.type==='tyre';
 const purchaseFields=p
   ?`<div class="field"><label>${T('purchaseCost')} (₹)</label><input type="number" name="cost" min="0" step="0.01" value="${amountField(p?.costPaise)}"></div>`
   :`<div class="field"><label for="first-bought-qty">${T('howManyBought')} *</label><input id="first-bought-qty" name="openingStock" type="number" min="${forceTyre?1:0}" step="1" required value="${forceTyre?1:0}"><small>${T('initialPurchaseHelp')}</small></div><div class="field"><label for="first-purchase-cost">${T('purchaseCost')} (₹) *</label><input id="first-purchase-cost" type="number" name="cost" min="0" step="0.01" required value="0"></div>`;
 const body=`<form id="price-form" data-id="${p?.id||''}"><div class="field-grid"><div class="field field-spread"><label>${T('description')} *</label><input name="name" maxlength="150" required value="${E(p?.name||'')}" placeholder="e.g. MRF ZVTV 185/65 R15 or Wheel alignment"></div>${forceTyre?'<input name="type" type="hidden" value="tyre">':`<div class="field"><label>${T('type')}</label><select name="type"><option value="service" ${!tyre?'selected':''}>${T('service')}</option><option value="tyre" ${tyre?'selected':''}>${T('tyre')}</option></select></div>`}<div class="field"><label>${tyre?T('sellingPrice'):T('price')} (₹) *</label><input type="number" min="0" step="0.01" name="price" required value="${amountField(p?.pricePaise)}"></div><div class="field"><label>${T('taxRate')}</label><input type="number" min="0" max="100" step="0.01" name="taxRate" value="${p?.taxBps?p.taxBps/100:0}"></div></div><div class="inventory-form-group" id="tyre-fields" ${tyre?'':'style="display:none"'}><h3>${p?T('tyreStockDetails'):T('newTyrePurchaseTitle')}</h3><p class="small-muted">${p?T('inventoryFormHint'):T('newTyrePurchaseHint')}</p><div class="field-grid tyre-purchase-fields">${purchaseFields}</div>${p?'':`<div class="first-purchase-preview"><span>${T('totalPurchaseCost')}</span><strong id="first-purchase-total">₹0.00</strong></div>`}<div class="tyre-extra-details"><h4>${T('tyreStockDetails')}</h4><div class="field-grid"><div class="field"><label>${T('brand')}</label><input name="brand" value="${E(p?.brand||'')}" placeholder="MRF / Apollo"></div><div class="field"><label>${T('model')}</label><input name="model" value="${E(p?.model||'')}"></div><div class="field"><label>${T('size')}</label><input name="size" value="${E(p?.size||'')}" placeholder="185/65 R15"></div><div class="field"><label>${T('supplier')}</label><input name="supplier" value="${E(p?.supplier||'')}"></div><div class="field"><label>${T('lowStockAt')}</label><input type="number" name="lowStockAt" min="0" step="1" value="${p?.lowStockAt??5}"></div></div></div></div></form>`;
 modal(p?T('editPriceItem'):tyre?T('addNewTyre'):T('newPriceItem'),tyre&&!p?T('newTyreHelp'):T('catalogSubtitle'),body,modalButtons('price-form',tyre&&!p?T('saveTyres'):T('save')));
}
function showStockModal(product=null,kind='purchase'){
 const purchase=kind==='purchase';
 const tyres=state.data.catalog.filter(p=>p.type==='tyre'&&p.isActive!==false).sort((a,b)=>a.name.localeCompare(b.name));
 if(purchase&&!tyres.length){showPriceModal(null,true);return;}
 if(!purchase&&(!product||product.type!=='tyre'))return toast(T('selectBoughtTyre'),true);
 const picked=product||tyres[0];
 const body=purchase?`<form id="purchase-form" data-id="${E(picked.id)}"><div class="field-grid"><div class="field field-spread"><label for="purchase-product">${T('selectBoughtTyre')} *</label><select name="productId" id="purchase-product" required>${tyres.map(p=>`<option value="${E(p.id)}" ${p.id===picked.id?'selected':''}>${E(p.name)} · ${p.stockQty||0} ${T('tyres').toLowerCase()}</option>`).join('')}<option value="__new__">＋ ${T('addNewTyre')}</option></select><small>${T('chooseOrNewHelp')}</small></div><div class="field"><label for="purchase-qty">${T('howManyBought')} *</label><input id="purchase-qty" name="qty" type="number" min="1" step="1" required value="1" autofocus></div><div class="field"><label for="purchase-cost">${T('purchaseCost')} (₹) *</label><input id="purchase-cost" name="cost" type="number" min="0" step="0.01" value="${amountField(picked.costPaise)}" required><small>${T('buyPriceHelp')}</small></div><div class="field"><label>${T('supplier')}</label><input id="purchase-supplier" name="supplier" maxlength="150" value="${E(picked.supplier||'')}"></div><div class="field"><label>${T('reference')}</label><input name="reference" maxlength="80" placeholder="Supplier bill number (optional)"></div></div><div class="stock-after-preview">${T('stockNow')}: <strong id="purchase-current">${picked.stockQty||0}</strong><span class="stock-preview-arrow">${I('arrow')}</span>${T('stockAfterBuy')}: <strong id="purchase-after">${(picked.stockQty||0)+1}</strong></div></form>`
 :`<form id="stock-form" data-id="${E(product.id)}"><div class="field-grid"><div class="field"><label>${T('adjustType')}</label><select name="direction"><option value="add">${T('increaseStock')}</option><option value="remove">${T('decreaseStock')}</option></select></div><div class="field"><label>${T('qty')} *</label><input name="qty" type="number" min="1" step="1" required value="1"></div><div class="field field-spread"><label>${T('adjustReason')} *</label><input name="reason" required maxlength="250" placeholder="Damage / physical count correction"></div></div></form>`;
 modal(purchase?T('addTyres'):T('correctStock'),purchase?T('chooseOrNewHelp'):`${E(product.name)} · ${T('inStock')}: ${product.stockQty||0}`,body,modalButtons(purchase?'purchase-form':'stock-form',purchase?T('saveTyres'):T('saveChanges')));
}
function updateInitialPurchasePreview(){
 const form=$('#price-form'),out=$('#first-purchase-total');
 if(!form||!out)return;
 const qty=Number(form.elements.namedItem('openingStock')?.value||0);
 const cost=Number(form.elements.namedItem('cost')?.value||0);
 out.textContent=Number.isSafeInteger(qty)&&qty>=0&&Number.isFinite(cost)&&cost>=0?M(Math.round(cost*100)*qty):'—';
}
function updatePurchasePreview(){
 const select=$('#purchase-product'),qty=$('#purchase-qty'),current=$('#purchase-current'),after=$('#purchase-after');
 if(!select||!qty||!current||!after)return;
 const product=state.data.catalog.find(p=>p.id===select.value);
 if(!product)return;
 const count=Number(qty.value);current.textContent=String(product.stockQty||0);
 after.textContent=Number.isSafeInteger(count)&&count>0?String((product.stockQty||0)+count):'—';
}
function showExpenseModal(){const body=`<form id="expense-form"><div class="field-grid"><div class="field"><label>${T('amount')} (₹) *</label><input name="amount" type="number" step="0.01" min="0.01" required placeholder="0.00" autofocus></div><div class="field"><label>${T('date')}</label><input name="date" type="date" value="${todayISO()}" max="${todayISO()}"></div><div class="field"><label>${T('category')}</label><select name="category"><option>Rent</option><option>Electricity</option><option>Employee salary</option><option>Maintenance</option><option>Supplies</option><option>Transport</option><option>Other</option></select></div><div class="field"><label>${T('paymentMethod')}</label><select name="method"><option value="cash">${T('cash')}</option><option value="upi">${T('upi')}</option><option value="card">${T('card')}</option><option value="other">${T('other')}</option></select></div><div class="field field-spread"><label>${T('description')}</label><textarea name="description" placeholder="What was this expense for?"></textarea></div></div></form>`;modal(T('recordExpense'),T('expensesSubtitle'),body,modalButtons('expense-form',T('saveExpense')));}
function showPaymentModal(o){const body=`<div class="muted-note note-inline">${I('info')}<span>${E(o.number)} · ${E(o.customerSnapshot.name||'')} · ${T('due')}: <b>${M(o.duePaise)}</b></span></div><form id="payment-form" data-id="${o.id}" data-confirmation="${uid()}" style="margin-top:21px"><div class="field-grid"><div class="field"><label>${T('amount')} (₹)</label><input name="amount" type="number" min="0.01" step="0.01" max="${amountField(o.duePaise)}" value="${amountField(o.duePaise)}" required></div><div class="field"><label>${T('paymentMethod')}</label><select name="method"><option value="cash">${T('cash')}</option><option value="upi">${T('upi')}</option><option value="card">${T('card')}</option><option value="other">${T('other')}</option></select></div><div class="field field-spread"><label>${T('reference')}</label><input name="reference" placeholder="Transaction reference (optional)"></div></div></form>`;modal(T('collectPayment'),'',body,modalButtons('payment-form',T('collectPayment')));}
function showRefundModal(o){const body=`<div class="muted-note note-inline">${I('alert')}<span>This only records a refund in the shop ledger. It does not transfer money through UPI, card, or a bank. Process the actual refund separately first.</span></div><form id="refund-form" data-id="${o.id}" style="margin-top:18px"><div class="field-grid"><div class="field"><label>Refund amount (₹)</label><input name="amount" type="number" min="0.01" step="0.01" max="${amountField(o.paidPaise)}" value="${amountField(o.paidPaise)}" required></div><div class="field"><label>Refund method</label><select name="method"><option value="cash">${T('cash')}</option><option value="upi">UPI</option><option value="card">${T('card')}</option><option value="other">${T('other')}</option></select></div><div class="field field-spread"><label>Refund transaction reference</label><input name="reference" placeholder="Optional receipt or bank reference"></div><div class="field field-spread"><label style="display:flex;gap:9px;align-items:flex-start"><input name="confirmed" type="checkbox" required style="width:17px;height:17px;margin:0">I confirm the money has actually been refunded outside this app.</label></div></div></form>`;modal('Record refund',`${E(o.number)} · Current net paid ${M(o.paidPaise)}`,body,modalButtons('refund-form','Record verified refund'));}
function showInvoiceModal(orderId){state.modalOrderId=orderId;const o=state.data.orders.find(x=>x.id===orderId);if(!o)return toast('Invoice not found',true);const html=invoiceInner({...o,paidPaise:o.paidPaise},'80',lang());const recipient=whatsappRecipient(o.customerSnapshot?.phone);const whatsappUrl=whatsappBillUrl(o,lang());const help=recipient?T('whatsappReadyForCustomer'):T('whatsappChooseChat');const body=`<div class="invoice-preview"><div class="invoice-paper">${html}</div></div>`;const footer=`${o.status!=='cancelled'?`<button class="button primary large" data-action="show-payment-qr" data-order="${E(o.id)}">Show payment QR</button>`:''}<div class="invoice-share-group"><a class="button whatsapp large" href="${E(whatsappUrl)}" target="_blank" rel="noopener noreferrer" aria-label="${T('shareWhatsApp')}">${I('message')}${T('shareWhatsApp')}</a><small>${help}</small></div><button class="button" data-copy-bill="${E(o.id)}">${I('file')}${T('copyWhatsAppBill')}</button><label class="invoice-format-label">${T('printFormat')} <select id="invoice-size" class="control"><option value="80">${T('thermal80')}</option><option value="58">${T('thermal58')}</option></select></label>${o.duePaise&&o.status!=='cancelled'?`<button class="button" data-pay-order="${o.id}">${I('money')}${T('collectPayment')}</button>`:''}${o.paidPaise>0&&o.status!=='cancelled'?`<button class="button" data-refund-order="${o.id}">Record refund</button>`:''}${o.paidPaise===0&&o.status!=='cancelled'?`<button class="button danger" data-cancel-order="${o.id}">${T('cancelInvoice')}</button>`:''}<button class="button primary" data-print-order="${o.id}">${I('printer')}${T('printReceipt')}</button>`;modal(E(o.number),`${E(o.customerSnapshot?.name||'')} · ${fmtDate(o.createdAt,true)} · ${o.status==='cancelled'?'CANCELLED':o.status.toUpperCase()}`,body,footer,true);}
function triggerPrint(orderId){const o=state.data.orders.find(x=>x.id===orderId);if(!o)throw Error('Invoice not found');const size=$('#invoice-size')?.value||'80';const doc=completeInvoiceHtml({...o,paidPaise:o.paidPaise},size,lang());const w=window.open('','_blank');if(!w){toast('Allow pop-ups to open print preview.',true);return;}w.opener=null;w.document.open();w.document.write(doc);w.document.close();}
function saveBlob(text,name,type='text/plain'){if(nativeAndroid()&&typeof window.TyreDeskAndroid.saveText==='function'){window.TyreDeskAndroid.saveText(text,name,type);return;}const b=new Blob([text],{type});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),12000);}
async function backup(){const json=await exportBackup();saveBlob(json,backupFileName(),'application/json');toast('Backup download requested. Check your Downloads or chosen folder.');}
async function backupToDrive(){const json=await exportBackup();const name=backupFileName();if(nativeAndroid()&&typeof window.TyreDeskAndroid.saveDriveBackup==='function'){window.TyreDeskAndroid.saveDriveBackup(json,name);return;}saveBlob(json,name,'application/json');toast('Now upload the downloaded backup file to your Google Drive.');window.open('https://drive.google.com/drive/u/0/my-drive','_blank','noopener');}
function restoreFromDrive(){if(!nativeAndroid())toast('Download the TyreDesk JSON backup from Google Drive, then select it here.');const file=$('#restore-file');if(file){file.click();return;}nav('settings');setTimeout(()=>$('#restore-file')?.click(),50);}
function changePinModal(){modal(T('changePassword'),T('securityNote'),`<form id="pin-form"><div class="field-grid"><div class="field field-spread"><label>Current PIN</label><input name="oldPin" type="password" pattern="[0-9]{4,12}" required inputmode="numeric"></div><div class="field"><label>New PIN</label><input name="newPin" type="password" pattern="[0-9]{4,12}" required inputmode="numeric"></div><div class="field"><label>${T('confirmPassword')}</label><input name="confirmPin" type="password" pattern="[0-9]{4,12}" required inputmode="numeric"></div></div></form>`,modalButtons('pin-form',T('saveChanges')));}
function installationInfo(){modal('Install TyreDesk',T('installHint'),`<div class="detail-list"><div class="detail-row"><span>Desktop Chrome / Edge</span><strong>Install icon in address bar</strong></div><div class="detail-row"><span>Android Chrome</span><strong>Menu → Add to Home screen / Install app</strong></div><div class="detail-row"><span>Offline after installation</span><strong>Yes</strong></div><div class="detail-row"><span>Requires initial HTTPS or localhost</span><strong>Yes</strong></div></div><div class="report-banner">A website opened directly from a file:// URL cannot register its offline service worker. Each device must install from a secure origin. Do not clear the browser's site data.</div>`, `<button class="button primary" data-action="close-modal">${T('continue')}</button>`);}
async function doAction(action,target){switch(action){
 case 'cloud-login':openCloudLogin();return;
 case 'cloud-sync':await syncCloud();return;
 case 'cloud-logout':await logoutCloud();return;
 case 'cloud-recover':{
   if(!window.confirm('Download a backup of this device, then replace its business records with the current cloud copy? Review the backup for any unsubmitted transactions.'))return;
   if(state.data?.settings)saveBlob(await exportBackup(),backupFileName(),'application/json');
   await syncCloud(true);return;
 }
 case 'draft-payment':{
   const calc=billValues();if(!calc||calc.error||!calc.due)return;
   modal('Confirm UPI receipt','Check the bank or UPI app for this transaction.',`<form id="draft-payment-form"><div class="field"><label>Amount actually received (₹)<input name="amount" type="number" min="0.01" step=".01" max="${amountField(calc.due)}" value="${amountField(calc.due)}" required></label></div><div class="field"><label>UPI reference (optional)<input name="reference" maxlength="160"></label></div><label class="consent"><input type="checkbox" name="verified" required> I verified this payment arrived.</label></form>`,modalButtons('draft-payment-form','Payment received'));return;
 }
 case 'show-payment-qr':await refresh();showPaymentQr(target.dataset.order);return;
 case 'qr-settings':closeModal();nav('settings');$('#payment-qr-file')?.focus();return;
 case 'menu':state.menuOpen=!state.menuOpen;render();return;
 case 'close-menu':state.menuOpen=false;render();return;
 case 'close-modal':closeModal();return;

 case 'add-line':state.bill.lines.push(newLine());rerenderBillLines();return;
 case 'add-customer':showCustomerModal();return;
 case 'add-reminder':showReminderModal();return;
 case 'edit-reminder':{const item=state.data.reminders.find(r=>r.id===target.dataset.reminder);if(item)showReminderModal(item);return;}
 case 'complete-reminder':{const item=state.data.reminders.find(r=>r.id===target.dataset.reminder);if(!item)return;if(!window.confirm(T('remindersConfirmDone')))return;await completeReminder(item.id);await refresh();toast(T('remindersCompleted'));return;}
 case 'add-price':showPriceModal();return;
 
 case 'buy-tyres':showStockModal(null,'purchase');return;
 case 'export-inventory':{const rows=state.data.catalog.filter(p=>p.type==='tyre').map(p=>[p.name,p.brand,p.model,p.size,p.supplier,p.stockQty||0,fromPaise(p.costPaise||0),fromPaise(p.pricePaise),p.lowStockAt]);saveBlob(toCSV(['Tyre','Brand','Model','Size','Supplier','Qty','Cost INR','Price INR','Low-stock at'],rows),`TyreDesk-inventory-${todayISO()}.csv`,'text/csv;charset=utf-8');return;}
 case 'add-expense':showExpenseModal();return;
 case 'clear-customer':state.bill.selectedCustomerId=null;state.bill.customerQuery='';state.bill.customerName='';state.bill.customerPhone='';render();return;
 case 'choose-backup-folder':if(nativeAndroid()){window.TyreDeskAndroid.chooseBackupFolder();}else if(hostedPwa()){try{const status=await pwaBackups.chooseFolder();Object.assign(backupInfo,status);toast('Backup folder connected. Your first local backup will save automatically.');render();scheduleAutoBackup();}catch(e){if(e.name!=='AbortError')throw e;}}else toast('Automatic PC backups are configured by your local launcher.');return;
 case 'backup':await backup();return;
 case 'backup-drive':await backupToDrive();return;
 case 'restore-drive':restoreFromDrive();return;
 case 'dismiss-drive-reminder':reminderStore.setItem(driveReminderDismissKey,driveDay());render();return;
 case 'restore':{const input=$('#restore-file');if(input){input.click();}else{nav('settings');setTimeout(()=>$('#restore-file')?.click(),50);}return;}
 case 'install':if(state.installPrompt){state.installPrompt.prompt();state.installPrompt=null;}else installationInfo();return;
 case 'change-pin':changePinModal();return;
 case 'persist-storage':if(navigator.storage?.persist){const ok=await navigator.storage.persist();toast(ok?'Persistent storage approved by browser.':'Browser did not grant persistent storage. Keep regular backups.',!ok);}else toast('Persistent storage API not supported. Keep regular backups.',true);return;
 case 'share-note':nav('sales');toast(T('openInvoiceToShare'));return;
 case 'save-bill':await saveBill();return;
 case 'export-sales':{const rows=state.data.orders.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(o=>[o.number,o.date,o.customerSnapshot.name,o.customerSnapshot.phone,o.vehicle,fromPaise(o.totals.grandPaise),fromPaise(o.paidPaise),fromPaise(o.duePaise),o.status]);saveBlob(toCSV(['Invoice','Date','Customer','Phone','Vehicle','Total INR','Paid INR','Due INR','Status'],rows),`TyreDesk-sales-${todayISO()}.csv`,'text/csv;charset=utf-8');return;}
 case 'export-customers':{const rows=state.data.customers.map(c=>[c.name,c.phone,state.data.vehicles.filter(v=>v.customerId===c.id).map(v=>v.reg).join('; '),c.notes||'']);saveBlob(toCSV(['Name','Phone','Vehicles','Notes'],rows),`TyreDesk-customers-${todayISO()}.csv`,'text/csv;charset=utf-8');return;}
 case 'export-expenses':{const rows=state.data.expenses.map(e=>[e.date,e.category,e.description,fromPaise(e.amountPaise),e.method]);saveBlob(toCSV(['Date','Category','Description','Amount INR','Method'],rows),`TyreDesk-expenses-${todayISO()}.csv`,'text/csv;charset=utf-8');return;}
 case 'export-reports':{const r=reportCalc(),rows=r.orders.map(o=>[o.number,o.date,o.customerSnapshot.name,fromPaise(o.totals.grandPaise),fromPaise(o.paidPaise),fromPaise(o.duePaise)]);saveBlob(toCSV(['Invoice','Date','Customer','Invoiced INR','Paid INR','Due INR'],rows),`TyreDesk-report-${state.reportStart}-to-${state.reportEnd}.csv`,'text/csv;charset=utf-8');return;}
 default:return;
}}
async function saveBill(){const b=state.bill;if(!b||b.saving)return;const calc=billValues();if(calc.error)throw Error(calc.error);let name=b.customerName,phone=b.customerPhone;
 if(!b.selectedCustomerId&&!name.trim()&&!phone.trim()){throw Error('Enter a customer name or phone number, or select an existing customer.');}
 if(!b.selectedCustomerId){
  const exactPhone=phone.trim()? (await searchCustomers(phone.trim(),40)).filter(c=>normalizePhone(c.phone)===normalizePhone(phone.trim())):[];
  const exactName=name.trim()? (await searchCustomers(name.trim(),40)).filter(c=>c.name.toLowerCase()===name.trim().toLowerCase()):[];
  const duplicates=[...new Map([...exactPhone,...exactName].map(c=>[c.id,c])).values()];
  if(duplicates.length&&!window.confirm('Potential duplicate customer(s):\n'+duplicates.slice(0,6).map(c=>c.name+' / '+(c.phone||'no phone')).join('\n')+'\n\nPress Cancel to select the existing customer using search, or OK to deliberately create a separate customer.')){throw Error('Select the existing customer above, or explicitly approve a separate customer.');}
 }
 if(b.lines.some(l=>!l.name.trim()))throw Error('Every invoice line must have a description.');
 if(b.lines.some(l=>!Number.isInteger(l.qty)||l.qty<1))throw Error('Quantity must be at least 1');
 b.saving=true;const btn=$('#save-bill');if(btn)btn.disabled=true;
 try{const input={requestId:b.requestId,customerId:b.selectedCustomerId,customerName:name,customerPhone:phone,vehicle:b.vehicle,items:b.lines.map(l=>({...l})),orderDiscount:calc.discount,paidPaise:toPaise(b.paid||0),draftReceipts:b.draftReceipts||[],paymentMethod:b.method,paymentReference:b.paymentReference,notes:b.notes,supplyMode:b.supplyMode};
 let order;try{order=await completeOrder(input);}catch(err){if(err.message.includes('another customer')){const confirmed=window.confirm(T('vehicleWarning')+'\n\nTransfer this vehicle to the current customer? Previous invoices will retain their original details.');if(!confirmed)throw Error('Invoice not saved: vehicle ownership needs confirmation.');order=await completeOrder({...input,confirmVehicleTransfer:true});}else throw err;}
 const id=order.id;state.bill=null;await refresh();nav('sales');showInvoiceModal(id);toast(T('invoiceSaved'));
 }finally{b.saving=false;if($('#save-bill'))$('#save-bill').disabled=false;}}
async function runForm(form){const f=new FormData(form);const v=k=>String(f.get(k)||'').trim();
 if(form.id==='draft-payment-form'){
   const b=state.bill,calc=billValues(),amount=toPaise(v('amount')),ref=v('reference');
   if(!f.has('verified')||!calc||calc.error||amount<=0||amount>calc.due)throw Error('Verify the payment and enter an amount within the balance due.');
   const old=b.draftReceipts||[];if(ref&&old.some(p=>p.reference.toLowerCase()===ref.toLowerCase()))throw Error('This UPI reference is already on the draft.');
   const updated={...b,draftReceipts:[...old,{id:uid(),amountPaise:amount,reference:ref,createdAt:now()}]};
   await saveReceivedDraft(updated);state.bill=updated;closeModal();render();toast('Payment confirmed on draft. Save to generate the invoice.');return;
 }
 if(form.id==='cloud-form'){
   if(!f.has('allowSync'))throw Error('Confirm cloud sharing for this shop.');
   let pin;
   if(!state.data.settings){const pinSalt=salt();if(!/^\d{4,12}$/.test(v('devicePin')))throw Error('Choose a 4–12 digit local PIN.');pin={pinSalt,pinHash:await hashPin(v('devicePin'),pinSalt)};}
   await loginCloud({username:v('username'),password:String(f.get('password')),project:v('project'),key:v('key'),pin});
   closeModal();await refresh();toast(cloudStatus().message);return;
 }
 if(form.id==='setup-form'){const legalConsent=consentRecord(f.get('legalConsent')==='on');const pin=v('pin');if(!/^\d{4,12}$/.test(pin))throw Error(T('pinMin'));if(pin!==v('confirmPin'))throw Error('PINs do not match');const gst=v('gstRegistered')==='true',gstin=v('gstin').toUpperCase();if(gst&&gstin.length!==15)throw Error('A GST-registered shop needs a valid 15-character GSTIN');
 const saltHex=salt(),pinHash=await hashPin(pin,saltHex);const s={id:'shop',legalConsent,name:v('name'),owner:v('owner'),phone:v('phone'),whatsapp:'',address:v('address'),city:v('city'),state:v('state'),gstin,invoicePrefix:v('invoicePrefix')||'INV',gstRegistered:gst,terms:'',logoData:'',language:v('language'),theme:'light',pinHash,pinSalt:saltHex,createdAt:now()};await saveSetting(s);sessionStorage.setItem('tyredesk-unlocked','yes');state.locked=false;await refresh();return;}
 if(form.id==='unlock-form'){const s=state.data.settings;if(await hashPin(v('pin'),s.pinSalt)!==s.pinHash)throw Error(T('wrongPin'));sessionStorage.setItem('tyredesk-unlocked','yes');state.locked=false;render();return;}
 if(form.id==='settings-form'){const s=state.data.settings;const gst=v('gstRegistered')==='true',gstin=v('gstin').toUpperCase();if(gst&&gstin.length!==15)throw Error('GST-registered businesses must enter a 15-character GSTIN');let logoData=s.logoData||'';const file=f.get('logo');if(file instanceof File&&file.size)logoData=await encodeLogo(file);await saveSetting({...s,name:v('name'),owner:v('owner'),phone:v('phone'),whatsapp:v('whatsapp'),address:v('address'),city:v('city'),state:v('state'),invoicePrefix:v('invoicePrefix').replace(/\W/g,'').slice(0,12)||'INV',gstRegistered:gst,gstin,terms:v('terms'),logoData,paymentQrData:f.get('removeQr')?'':await encodePaymentQr(f.get('paymentQr'),s.paymentQrData||'')});await refresh();toast(T('saveChanges'));return;}
 if(form.id==='reminder-form'){const date=new Date(v('due'));if(!v('due')||!Number.isFinite(date.getTime()))throw Error(T('remindersInvalidDate'));await saveReminder({id:form.dataset.id||undefined,title:v('title'),notes:v('notes'),dueAt:date.toISOString()});await refresh();closeModal();toast(T('remindersSaved'));return;}
 if(form.id==='customer-form'){const id=form.dataset.id;let c=await upsertCustomer({id:id||undefined,name:v('name'),phone:v('phone'),notes:v('notes')});if(v('vehicle')){try{await setVehicle(v('vehicle'),c.id);}catch(err){if(err.message.includes('different customer')&&window.confirm(T('vehicleWarning')+' Transfer association?'))await setVehicle(v('vehicle'),c.id,true);else throw err;}}await refresh();closeModal();toast(T('saveChanges'));return;}
 if(form.id==='price-form'){const id=form.dataset.id;const price=toPaise(v('price'));if(!Number.isSafeInteger(price)||price<0)throw Error('Invalid price');const taxBps=Math.round(Number(v('taxRate'))*100);await addCatalogItem({id:id||undefined,name:v('name'),type:v('type'),pricePaise:price,taxBps,brand:v('brand'),model:v('model'),size:v('size'),supplier:v('supplier'),costPaise:toPaise(v('cost')||'0'),lowStockAt:Number(v('lowStockAt')||0),openingStockQty:Number(v('openingStock')||0)});await refresh();closeModal();toast(T('saveChanges'));return;}
 if(form.id==='purchase-form'){await recordPurchase({productId:v('productId'),qty:Number(v('qty')),costPaise:toPaise(v('cost')),supplier:v('supplier'),reference:v('reference')});await refresh();closeModal();toast(T('stockUpdated'));return;}
 if(form.id==='stock-form'){const qty=Number(v('qty'));await adjustStock(form.dataset.id,v('direction')==='remove'?-qty:qty,v('reason'));await refresh();closeModal();toast(T('stockUpdated'));return;}
 if(form.id==='expense-form'){const money=toPaise(v('amount'));await addExpense({amountPaise:money,date:v('date'),category:v('category'),description:v('description'),method:v('method')});await refresh();closeModal();toast(T('recorded'));return;}
 if(form.id==='payment-form'){if(!window.confirm('Confirm you have actually received '+M(toPaise(v('amount')))+' from the customer?'))return;const id=form.dataset.id,money=toPaise(v('amount'));await addPayment(id,money,v('method'),v('reference'),form.dataset.confirmation);await refresh();showInvoiceModal(id);toast(T('paymentRecorded'));return;}
 if(form.id==='qr-payment-form'){if(!f.get('verified'))throw Error('Verify receipt in your bank or UPI app first.');const money=toPaise(v('amount'));if(!window.confirm('Record '+M(money)+' as actually received? Displaying the QR alone is not payment.'))return;await addPayment(form.dataset.id,money,'upi',v('reference'),form.dataset.confirmation);const id=form.dataset.id;await refresh();showInvoiceModal(id);toast('Payment recorded.');return;}
 if(form.id==='refund-form'){if(!f.get('confirmed'))throw Error('Confirm that you have already refunded the payment.');const id=form.dataset.id,money=toPaise(v('amount'));await recordRefund(id,money,v('method'),v('reference'));await refresh();showInvoiceModal(id);toast('Refund recorded in the ledger.');return;}
 if(form.id==='pin-form'){const s=state.data.settings;if(await hashPin(v('oldPin'),s.pinSalt)!==s.pinHash)throw Error('Current PIN is incorrect');if(!/^\d{4,12}$/.test(v('newPin')))throw Error('Use a 4–12 digit PIN');if(v('newPin')!==v('confirmPin'))throw Error('New PINs do not match');const saltHex=salt(),pinHash=await hashPin(v('newPin'),saltHex);await saveSetting({...s,pinHash,pinSalt:saltHex});await addAudit('owner-pin-changed');await refresh();closeModal();toast(T('saveChanges'));return;}
}
document.addEventListener('click',async event=>{
 try{
  if(event.target.matches('[data-close-modal]')){closeModal();return;}
  const target=event.target.closest('button,[data-invoice],[data-customer]');if(!target)return;
  if(target.dataset.nav){nav(target.dataset.nav);return;}
  if(target.dataset.action){await doAction(target.dataset.action,target);return;}
  if(target.dataset.invoice){showInvoiceModal(target.dataset.invoice);return;}
  if(target.dataset.customer){const c=state.data.customers.find(x=>x.id===target.dataset.customer);if(c)showCustomerModal(c);return;}
  if(target.dataset.addCatalog){const p=state.data.catalog.find(x=>x.id===target.dataset.addCatalog);if(p){state.bill.lines.push(newLine(p));rerenderBillLines();}return;}
  if(target.dataset.removeLine){state.bill.lines=state.bill.lines.filter(l=>l.key!==target.dataset.removeLine);rerenderBillLines();return;}
  if(target.dataset.selectCustomer){const c=state.data.customers.find(x=>x.id===target.dataset.selectCustomer);if(c){state.bill.selectedCustomerId=c.id;state.bill.customerName=c.name;state.bill.customerPhone=c.phone;state.bill.customerQuery='';render();}return;}
  if(target.dataset.editPrice){const p=state.data.catalog.find(x=>x.id===target.dataset.editPrice);if(p)showPriceModal(p);return;}
  if(target.dataset.stockIn){showStockModal(state.data.catalog.find(x=>x.id===target.dataset.stockIn),'purchase');return;}
  if(target.dataset.stockAdjust){showStockModal(state.data.catalog.find(x=>x.id===target.dataset.stockAdjust),'adjust');return;}
  if(target.dataset.payOrder){const o=state.data.orders.find(x=>x.id===target.dataset.payOrder);if(o)showPaymentModal(o);return;}
  if(target.dataset.refundOrder){const o=state.data.orders.find(x=>x.id===target.dataset.refundOrder);if(o)showRefundModal(o);return;}
  if(target.dataset.cancelOrder){const reason=window.prompt('Cancellation reason (required):');if(!reason?.trim())return;if(!window.confirm('Cancel this unpaid invoice? This cannot be undone.'))return;await cancelOrder(target.dataset.cancelOrder,reason);await refresh();closeModal();toast('Invoice cancelled.');return;}
  if(target.dataset.printOrder){triggerPrint(target.dataset.printOrder);return;}
  if(target.dataset.copyBill){const o=state.data.orders.find(x=>x.id===target.dataset.copyBill);if(!o)throw Error('Invoice not found');await navigator.clipboard.writeText(formatWhatsAppBill(o,lang()));toast(T('whatsappCopied'));return;}
 }catch(e){errorMessage(e);}
});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.id)return;event.preventDefault();if(form.dataset.busy==='yes')return;form.dataset.busy='yes';const btn=form.querySelector('button[type="submit"]')||$(`button[form="${form.id}"]`);if(btn)btn.disabled=true;try{await runForm(form);}catch(e){errorMessage(e);}finally{delete form.dataset.busy;if(btn&&btn.isConnected)btn.disabled=false;}});
document.addEventListener('input',event=>{
 const target=event.target;
 if(target.closest('#price-form')&&(target.name==='openingStock'||target.name==='cost')){updateInitialPurchasePreview();return;}
 if(target.id==='purchase-qty'){updatePurchasePreview();return;}
 if(target.id==='page-search'){const pos=target.selectionStart;state.search=target.value;render();const input=$('#page-search');input?.focus();try{input?.setSelectionRange(pos,pos);}catch{}return;}
 if(target.id==='customer-lookup'){state.bill.customerQuery=target.value;state.bill.selectedCustomerId=null;const q=target.value.trim();if(/^\+?[\d\s-]+$/.test(q)){state.bill.customerPhone=q;const phone=$('#bill-customer-phone');if(phone)phone.value=q;}else if(q){state.bill.customerName=q;const n=$('#bill-customer-name');if(n)n.value=q;}loadCustomerSuggestions(target.value).catch(errorMessage);return;}
 const billFields={'bill-customer-name':'customerName','bill-customer-phone':'customerPhone','bill-vehicle':'vehicle','bill-discount-value':'billDiscountValue','bill-paid':'paid','bill-reference':'paymentReference','bill-notes':'notes'};
 if(billFields[target.id]&&state.bill){state.bill[billFields[target.id]]=target.value;updateBillTotals();return;}
 if(target.dataset.lineField&&state.bill){const node=target.closest('[data-line]');const line=state.bill.lines.find(l=>l.key===node?.dataset.line);if(!line)return;const prop=target.dataset.lineField;switch(prop){case'name':line.name=target.value;break;case'qty':line.qty=Number(target.value);break;case'unitPaise':line.unitPaise=toPaise(target.value);break;case'discountValue':line.discount.value=line.discount.type==='percent'?Math.round(Number(target.value)*100):toPaise(target.value);break;default:break;}updateBillTotals();return;}
});
document.addEventListener('change',async event=>{const el=event.target;try{
 if(el.id==='purchase-product'){
   if(el.value==='__new__'){showPriceModal(null,true);return;}
   const product=state.data.catalog.find(p=>p.id===el.value);
   if(product){const cost=$('#purchase-cost'),supplier=$('#purchase-supplier');if(cost)cost.value=amountField(product.costPaise);if(supplier)supplier.value=product.supplier||'';updatePurchasePreview();}
   return;
 }
 if(el.name==='type'&&el.closest('#price-form')){const fields=$('#tyre-fields');if(fields)fields.style.display=el.value==='tyre'?'':'none';return;}
 if(el.id==='invoice-size'){const selected=el.value;const o=state.data.orders.find(x=>x.id===state.modalOrderId);const host=$('.invoice-paper');if(o&&host)host.innerHTML=invoiceInner({...o,paidPaise:o.paidPaise},selected,lang());return;}
 if(el.id==='sales-filter'){state.salesStatus=el.value;render();return;}
 if(el.id==='report-from'||el.id==='report-to'){if(el.id==='report-from')state.reportStart=el.value;else state.reportEnd=el.value;if(state.reportStart>state.reportEnd){toast('The start date must be on or before the end date.',true);return;}render();return;}
 if(el.id==='setting-language'){await saveSetting({...state.data.settings,language:el.value});await refresh();return;}
 if(el.id==='setting-theme'){await saveSetting({...state.data.settings,theme:el.value});await refresh();return;}
 if(el.id==='bill-discount-type'){state.bill.billDiscountType=el.value;state.bill.billDiscountValue='0';const input=$('#bill-discount-value');if(input)input.value='0';updateBillTotals();return;}
 if(el.id==='bill-method'){state.bill.method=el.value;return;}
 if(el.id==='bill-supply'){state.bill.supplyMode=el.value;updateBillTotals();return;}
 if(el.dataset.lineField==='discountType'){const line=state.bill.lines.find(l=>l.key===el.closest('[data-line]').dataset.line);if(!line)return;line.discount.type=el.value;line.discount.value=0;const input=el.closest('.discount-inline').querySelector('input');if(input)input.value='0';updateBillTotals();return;}
 if(el.id==='restore-file'){if(!el.files?.length)return;const file=el.files[0];if(file.size>100_000_000)throw Error('Backup file is larger than 100 MB');const backupText=await file.text();if(!window.confirm(T('restoreWarning')+'\n\nThis will replace this device’s records and disconnect it from cloud sync. The shared cloud copy is kept. Back up the current device first. Continue?')){el.value='';return;}const counts=await restoreOffline(()=>restoreBackup(backupText,{disconnectCloud:true}));sessionStorage.removeItem('tyredesk-unlocked');state.locked=true;state.bill=null;await refresh();toast(T('restoreSuccess')+' · '+counts.orders+' invoices.');return;}
 }catch(err){errorMessage(err);}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.modal)closeModal();else if(state.menuOpen){state.menuOpen=false;render();}}if(e.ctrlKey&&e.key.toLowerCase()==='k'&&!state.locked){e.preventDefault();nav('billing');}});
// A natural left swipe on the open drawer closes it; vertical scrolling remains untouched.
let menuSwipeStart=null;
document.addEventListener('touchstart',event=>{
 if(!state.menuOpen||!event.target.closest('#app-sidebar')||event.touches.length!==1)return;
 const touch=event.touches[0];menuSwipeStart={x:touch.clientX,y:touch.clientY};
},{passive:true});
document.addEventListener('touchend',event=>{
 if(!menuSwipeStart)return;
 const start=menuSwipeStart;menuSwipeStart=null;
 const touch=event.changedTouches[0];if(!touch||!state.menuOpen)return;
 const dx=touch.clientX-start.x,dy=touch.clientY-start.y;
 if(dx < -80&&Math.abs(dx)>Math.abs(dy)*1.5){state.menuOpen=false;render();}
},{passive:true});

// Keep the focused field visible above Android's soft keyboard and avoid
// displaying a bottom navigation bar above the keyboard.
if(window.visualViewport){
 let fullHeight=window.visualViewport.height;
 const viewportChanged=()=>{
  const vv=window.visualViewport;
  const focused=document.activeElement;
  const typing=focused?.matches?.('input:not([type="checkbox"]):not([type="radio"]),textarea,select');
  if(!typing)fullHeight=Math.max(fullHeight,vv.height);
  const keyboardOpen=!!typing&&fullHeight-vv.height>130;
  document.documentElement.classList.toggle('keyboard-open',keyboardOpen);
  document.documentElement.style.setProperty('--visible-screen-height',Math.round(vv.height)+'px');
 };
 window.visualViewport.addEventListener('resize',viewportChanged);
 window.visualViewport.addEventListener('scroll',viewportChanged);
 document.addEventListener('focusin',event=>{
  if(!event.target.matches('input,textarea,select'))return;
  fullHeight=Math.max(fullHeight,window.visualViewport.height);
  setTimeout(()=>{
   viewportChanged();
   const target=event.target;
   if(target.isConnected&&document.activeElement===target){
    target.scrollIntoView({block:'center',behavior:'smooth'});
   }
  },210);
 });
 document.addEventListener('focusout',()=>setTimeout(viewportChanged,220));
 viewportChanged();
}
